const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Alisal Fire was in Santa Barbara County, California
  var fireRegion = ee.Geometry.Rectangle([-120.5, 34.3, -119.8, 34.8]);
  var startDate = '2021-10-01';
  var endDate = '2021-10-31'; // Using full month since MCD64A1 is monthly

  // 2. Data Acquisition - MODIS Burned Area Monthly product
  var burnedArea = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(fireRegion);

  var collectionSize = burnedArea.size().getInfo();
  print('October 2021 Burned Area Images: ' + collectionSize);

  if (collectionSize === 0) {
    print('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get burned area for October 2021
  var octoberBurned = burnedArea.first().select('BurnDate');

  // Create mask for burned pixels (values 1-366 indicate burn day of year)
  var burnedMask = octoberBurned.gt(0).and(octoberBurned.lte(366));
  var burnedAreaImage = burnedMask.selfMask();

  // 4. Calculate burned area statistics
  var pixelArea = burnedAreaImage.multiply(ee.Image.pixelArea()); // Area in square meters
  var totalArea = pixelArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: fireRegion,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate');

  var pixelCount = burnedAreaImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: fireRegion,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate');

  var areaSqM = totalArea.getInfo();
  var count = pixelCount.getInfo();

  print('Burned pixels: ' + count);

  if (count === 0 || areaSqM === null) {
    print('No burned area detected in region.');
    print('<answer>C2</answer>');
    return;
  }

  // Convert from square meters to acres
  var areaAcres = areaSqM / 4046.86;
  print('Burned area: ' + areaAcres.toFixed(2) + ' acres');

  // 5. Validation & Final Answer
  if (areaAcres === null || areaAcres < 0 || areaAcres > 1000000) {
    print('<answer>C3</answer>');
  } else if (areaAcres < 10000) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
